// PRIMARY: network/endpoint.go:NewExecutionRPCClient (lines 129-159)
func NewExecutionRPCClient(ctx context.Context, endpoint Endpoint, headers http.Header) (*gethRPC.Client, error) {
	// Need to handle ipc and http
	var client *gethRPC.Client
	u, err := url.Parse(endpoint.Url)
	if err != nil {
		return nil, err
	}
	switch u.Scheme {
	case "http", "https":
		client, err = gethRPC.DialOptions(ctx, endpoint.Url, gethRPC.WithHTTPClient(endpoint.HttpClient()), gethRPC.WithHeaders(headers))
		if err != nil {
			return nil, err
		}
	case "", "ipc":
		client, err = gethRPC.DialIPC(ctx, endpoint.Url)
		if err != nil {
			return nil, err
		}
	default:
		return nil, fmt.Errorf("no known transport for URL scheme %q", u.Scheme)
	}
	return client, nil
}

// RELATED: api/apiutil/header.go:ParseAccept (lines 53-83)
func ParseAccept(header string) []mediaRange {
	if header == "" {
		return []mediaRange{{mt: "*/*", q: 1, spec: 0, raw: "*/*"}}
	}

	var out []mediaRange
	for _, field := range strings.Split(header, ",") {
		if r, ok := parseMediaRange(field); ok {
			out = append(out, r)
		}
	}

	sort.SliceStable(out, func(i, j int) bool {
		ei, ej := hasExplicitQ(out[i]), hasExplicitQ(out[j])
		if ei != ej {
			return ei // explicit beats implicit
		}
		if out[i].q != out[j].q {
			return out[i].q > out[j].q
		}
		return out[i].spec > out[j].spec
	})
	return out
}

